        title: "Build the Chat Event System",
        tagline: "A simple publish-subscribe bus.",
        goal: "Create the ChatEvents object with on(event, cb) to subscribe and emit(event, data) to broadcast — other modules will use this to communicate without direct references.",
        logic: [
          "ChatEvents.listeners is an object where keys are event names and values are arrays of callback functions.",
          "on(event, cb) pushes a callback into the array for that event name — creates the array if it doesn't exist.",
          "emit(event, data) calls every callback registered for that event, passing the data argument.",
          "onMessageReceived(userId) is a helper that emits both 'messageReceived' and 'conversationUpdated' events.",
          "This pattern decouples Chat from App — Chat doesn't need to know who's listening."
        ],
        logicCode: [
          "const ChatEvents = {",
          "  listeners: {},",
          "",
          "  on(event, cb) {",
          "    if (!this.listeners[event]) this.listeners[event] = [];",
          "    this.listeners[event].push(cb);",
          "  },",
          "",
          "  emit(event, data) {",
          "    (this.listeners[event] || []).forEach(cb => cb(data));",
          "  },",
          "",
          "  onMessageReceived(userId) {",
          "    this.emit('messageReceived', userId);",
          "    this.emit('conversationUpdated', userId);",
          "  },",
          "",
          "  onMessageSent(userId, msg) {",
          "    this.emit('messageSent', { userId: userId, message: msg });",
          "    this.emit('conversationUpdated', userId);",
          "  }",
          "};"
        ],
