          "    3: { name: 'David', style: 'Funny',",
          "      replies: [\"Haha, no way! 😂\", \"Bro, that's epic! 🔥\", \"LMAO you're kidding 😂\"] },",
          "    // ... 5 more contacts with unique reply styles",
          "  },",
          "",
          "  init() {",
          "    this.conversations = Storage.get('chat_messages', {});",
