          "  },",
          "",
          "  sendMessage(text, type, extra) {",
          "    if (!this.activeChat) return null;",
          "    const msg = { id: 'msg_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),",
          "      senderId: (Users.currentUser || Users.sampleUsers[0]).id,",
          "      text: text, timestamp: Date.now(), type: type, status: 'sent' };",
          "    Object.assign(msg, extra);",
