          "}",
          "",
          "function buildRepoCard(repo) {",
          "  const langColor = getLanguageColor(repo.language);",
          "  return `",
          "    <div class=\"repo-card\" role=\"listitem\">",
          "      <div class=\"repo-card__name\">",
          "        <a href=\"${repo.html_url}\" target=\"_blank\" rel=\"noopener noreferrer\">",
          "          ${escapeHtml(repo.name)}",
          "        </a>",
          "      </div>",
          "      <p class=\"repo-card__description\">",
          "        ${repo.description ? escapeHtml(repo.description) : 'No description provided.'}",
          "      </p>",
          "      <div class=\"repo-card__meta\">",
          "        ${repo.language ? `<span class=\"repo-card__language\"><span class=\"repo-card__lang-dot\" style=\"background: ${langColor};\"></span>${escapeHtml(repo.language)}</span>` : ''}",
          "        <span class=\"repo-card__stat\">Stars: ${repo.stargazers_count ?? 0}</span>",
          "        <span class=\"repo-card__stat\">Forks: ${repo.forks_count ?? 0}</span>",
          "      </div>",
          "    </div>",
          "  `;",
          "}",
          "",
          "function getLanguageColor(language) {",
          "  const colors = {",
          "    JavaScript: '#f1e05a', TypeScript: '#3178c6', Python: '#3572A5',",
          "    Java: '#b07219', Go: '#00ADD8', 'C++': '#f34b7d',",
          "    HTML: '#e34c26', CSS: '#563d7c', Vue: '#41b883',",
