          "    this.el.innerHTML = '';",
          "    const processed = this._getProcessedTaskIds(tasks, taskOrder, filters, sort, search);",
          "    columns.forEach(col => {",
          "      const colEl = this._createColumn(col, processed[col.id] || [], tasks);",
          "      this.el.appendChild(colEl);",
          "    });",
          "  },",
          "  _createColumn(column, taskIds, tasks) {",
