          "",
          "function formatNumber(num) {",
          "  if (!num || num === 'N/A') return 'N/A';",
          "  const parsed = Number(String(num).replace(/,/g, ''));",
          "  if (isNaN(parsed)) return num;",
          "  return parsed.toLocaleString('en-US');",
          "}",
