          "// 1. Timer configuration",
          "const TIMER_SECONDS = 15;",
          "",
          "// 2. State variables",
          "let timeLeft = TIMER_SECONDS;",
          "let timerInterval = null;",
          "",
          "// 3. Start the timer",
          "function startTimer() {",
          "  if (timerInterval) return;",
          "  timerInterval = setInterval(() => {",
          "    timeLeft--;",
          "    updateTimerDisplay();",
          "    if (timeLeft <= 0) {",
          "      clearTimer();",
          "      handleTimeout();",
          "    }",
          "  }, 1000);",
          "}",
          "",
          "// 4. Update the timer display",
          "function updateTimerDisplay() {",
