        "  text-align: center;",
        "}",
        "",
        ".header h1 { font-size: 1.6rem; }",
        ".header p { color: #6b7280; margin-top: 6px; font-size: 0.95rem; }",
        "",
        ".line {",
        "  width: 70px;",
        "  height: 4px;",
        "  background: #2563eb;",
        "  border-radius: 10px;",
        "  margin: 20px auto 28px;",
