        "  margin-top: 12px;",
        "  font-size: 1rem;",
        "  font-weight: 600;",
        "}",
        "",
        ".buttons { display: flex; gap: 12px; justify-content: center; }",
        "",
        ".buttons button {",
        "  border: none;",
        "  background: #2563eb;",
        "  color: #ffffff;",
        "  padding: 10px 22px;",
        "  border-radius: 10px;",
        "  font-size: 0.95rem;",
        "  font-weight: 600;",
