        "}",
        "",
        ".main-wrapper {",
        "  flex: 1;",
        "  display: flex;",
        "  justify-content: center;",
        "  align-items: center;",
        "  padding: 20px 0;",
        "}",
        "",
        ".container {",
        "  width: 100%;",
        "  max-width: 720px;",
        "  background: #ffffff;",
        "  border-radius: 24px;",
        "  padding: 40px;",
