        "  color: #111827;",
        "  background: #ffffff;",
        "}",
        "",
        "#taskInput:focus { border-color: #4f46e5; box-shadow: 0 0 0 3px #eef2ff; }",
        "",
        "#addTaskBtn {",
        "  width: 180px;",
        "  border: none;",
        "  border-radius: 12px;",
        "  cursor: pointer;",
        "  color: #ffffff;",
        "  font-size: 1rem;",
        "  font-weight: 600;",
        "  background: #4f46e5;",
        "  transition: all 0.2s ease;",
        "}",
        "",
        "#addTaskBtn:hover { background: #4338ca; transform: translateY(-2px); }",
        "",
        ".progress-section {",
        "  background: #f8fafc;",
        "  border-radius: 16px;",
        "  padding: 20px;",
        "  margin-bottom: 30px;",
        "  border: 1px solid #e5e7eb;",
        "}",
        "",
        ".progress-text {",
        "  display: flex;",
        "  justify-content: center;",
        "  margin-bottom: 15px;",
        "  font-weight: 600;",
        "  color: #6b7280;",
        "}",
        "",
        ".progress-bar {",
        "  width: 100%;",
        "  height: 12px;",
        "  border-radius: 20px;",
        "  background: #e5e7eb;",
        "  overflow: hidden;",
        "}",
        "",
        "#progressFill {",
        "  width: 0%;",
        "  height: 100%;",
        "  border-radius: 20px;",
