        ".task:hover { border-color: #4f46e5; transform: translateY(-2px); }",
        "",
        ".task input { width: 20px; height: 20px; cursor: pointer; }",
        "",
        ".task span {",
        "  font-size: 1rem;",
        "  color: #111827;",
        "  word-break: break-word;",
        "}",
        "",
        ".completed { text-decoration: line-through; color: #9ca3af !important; }",
