        "  font-size: 1rem;",
        "  font-weight: 600;",
        "}",
        "",
        ".edit-btn { color: #4f46e5; }",
        ".delete-btn { color: #dc2626; }",
        "",
        ".stats {",
        "  display: grid;",
        "  grid-template-columns: repeat(3, 1fr);",
